function search(query=''){title('SEARCH','Search the guide.');main.append(searchForm(query));if(!query.trim()){main.append(text('Search an exact variant, nickname, boss, recipe, mode or guide.','muted'));return;}const q=query.toLowerCase(),rows=[];for(const h of heroes)if([h.name,h.key,...h.aliases].join(' ').toLowerCase().includes(q))rows.push({name:h.name,type:'Character · '+h.attribute,url:'#hero/'+h.key});for(const b of E.encounters)if(JSON.stringify(b).toLowerCase().includes(q))rows.push({name:b.name,type:'Boss Lab',url:'#bosses/'+b.id});for(const m of D.modes.modes)if(JSON.stringify(m).toLowerCase().includes(q))rows.push({name:m.name,type:'Mode walkthrough',url:'#modes/'+m.id});for(const v of D.videos)if([v.title,v.channel,v.topic].join(' ').toLowerCase().includes(q))rows.push({name:v.title,type:'Video · '+v.channel,url:v.url});for(const c of E.coffee)if(JSON.stringify(c).toLowerCase().includes(q))rows.push({name:c.name,type:'Coffee recipe',url:'#coffee'});for(const[k,n]of[['start','Start here new account first steps'],['best-teams','Best teams meta PvE arena guild war carnival boss world boss owl bin noro centipede weekly challenge organization capture'],['buy','What to buy shop prices passes'],['tiers','Tier list ranking'],['spend','Diamond Spring spending budget pity calculator'],['banners','Banner live Halloween Hinami history Green Juzo'],['cells','Cells potential equipment'],['progression','Beginner progression daily checklist']])if(n.toLowerCase().includes(q))rows.push({name:n,type:'Guide / tool',url:'#'+k});main.append(text(rows.length+' results','results-count'));if(!rows.length)main.append(text('No exact match. Try a shorter name or variant.','empty'));for(const r of rows)main.append(el('a',{href:r.url,class:'search-result',...(safeURL(r.url)?{target:'_blank',rel:'noopener noreferrer'}:{})},el('strong',{},r.name),el('small',{},r.type)));}
function render(){let parts;try{parts=decodeURIComponent(location.hash.slice(1)||'home').split('/');}catch{parts=['home'];}const[r,id,tab]=parts;main.replaceChildren();headerContext();document.querySelectorAll('header nav a').forEach(a=>{const active=a.getAttribute('href')==='#'+r;a.classList.toggle('on',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});try{({home,start:startHere,'best-teams':()=>bestTeams(id),meta:()=>metaPage(id),challenges,run:recommender,buy,tiers:tierList,characters:codex,hero:()=>heroDetail(id,tab),teams:()=>teams(id),bosses:()=>bosses(id),banners,spend:()=>{title('TOOLS','Diamond and pull calculators.','Enter the numbers from your game. Nothing is assumed.');howto('spend');const tools=el('div');main.append(tools);window.Economy.mount(tools,profile);},modes:()=>modeLibrary(id),cells,coffee,videos:()=>videos(id),progression,account,sources,search:()=>search(parts.slice(1).join('/'))}[r]||home)();enNote(r);}catch(e){main.append(text('This section could not render. Your saved profile remains local. Try another section or export a backup.','notice'));console.error(e);}if(storageWarning)main.prepend(text('Storage unavailable: changes last for this tab only. Export a profile backup.','notice'));window.scrollTo(0,0);document.title='Tokyo Ghoul · '+(r==='hero'?byKey.get(id)?.name||'Character':(routes.find(x=>x[0]===r)||[0,r[0].toUpperCase()+r.slice(1)])[1]);}
/* PT/ES: pages built from game files, creator videos or the old guide say that text stays in English. */
const EN_DATA=['hero','bosses','modes','cells','coffee','videos','banners','sources','progression'];
function enNote(r){const L=window.TGI18N;if(!L||L.lang==='en'||!EN_DATA.includes(r))return;const h=main.querySelector('h1'),n=text('Game text on this page is in English (copied from the game files).','subtle en-note');if(h)(h.nextElementSibling&&h.nextElementSibling.classList.contains('section-intro')?h.nextElementSibling:h).after(n);else main.prepend(n);}
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView();});
